# AUTO-GENERATED by Claude Code
# Purpose: what the debug panel (bug icon / Alt+D) shows: every outside call the app makes
#          (start.gg GraphQL, HTTP fetches, agent turns, tool steps; ds.util.logging.log_call),
#          kept in memory only, the newest MAX_RECORDS, gone when the backend restarts.
# Usage: install() once at import (state.py); rows(...) / stats(...) when the panel opens.
#        A new kind of record is one function in LOG_FORMATS.
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
import json
import resource
import sys
import threading
import time
from collections import deque
from collections.abc import Callable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import polars as pl
from pydantic import BaseModel

from ds.data.raw.startgg.client import MAX_REQUESTS_PER_MINUTE
from ds.util.http import curl_command
from ds.util.logging import enable_call_logs, logger

# ~2.5 KB a record (measured Nov 2026; mostly the request headers, a GraphQL query text is
# shared with queries.py, not copied): 2000 is about 5 MB, bounded however long it runs
MAX_RECORDS = 2000
# rows sent to the browser at once (newest first); the rest stay here
MAX_ROWS = 300
SESSION_CHARS = 8  # a session is shown by the start of its client token
_WINDOW = 60.0  # start.gg's rate window, seconds
# Details shown folded inside an unfolded row (long text you only sometimes want), by label.
FOLDED_DETAILS = frozenset({"tool response"})

_records: deque[dict[str, Any]] = deque(maxlen=MAX_RECORDS)
_seq = 0
_lock = threading.Lock()
_installed = False


def session_id(token: str) -> str:
    """How a session shows in the log (and what `logger.contextualize(session=...)` sets)."""
    return token[:SESSION_CHARS]


def _sink(message: Any) -> None:
    global _seq  # noqa: PLW0603  # one counter for the one in-memory log
    record = message.record
    extra = record["extra"]
    if "kind" not in extra:
        return
    with _lock:
        _seq += 1
        _records.append(
            {
                "id": _seq,
                "time": record["time"].timestamp(),
                "level": record["level"].name,
                "message": record["message"],
            }
            | extra
        )


def install() -> None:
    """Turn on ds's call logs and keep them here (once per process)."""
    global _installed  # noqa: PLW0603
    if _installed:
        return
    _installed = True
    enable_call_logs()
    logger.add(_sink, level="INFO", filter=lambda r: "kind" in r["extra"], enqueue=False)


def clear(session: str = "") -> None:
    """Forget the records, all of them or one session's."""
    with _lock:
        kept = [r for r in _records if session and r.get("session") != session]
        _records.clear()
        _records.extend(kept)


# -- formatting: one function per kind --------------------------------------------------


@dataclass
class LogView:
    summary: str
    badges: list[str] = field(default_factory=list)
    details: list[tuple[str, str]] = field(default_factory=list)


def _json(value: Any) -> str:
    return json.dumps(value, indent=2, default=str, ensure_ascii=False)


def _size(n: Any) -> str:
    if not isinstance(n, int):
        return "?"
    return f"{n / 1024:.1f} KB" if n >= 1024 else f"{n} B"  # noqa: PLR2004  # 1 KB


def _common(record: dict[str, Any]) -> list[tuple[str, str]]:
    """Details every kind shows, last: what it was part of, where it came from, the error."""
    rows = []
    if record.get("tool_call_id"):
        rows.append(("tool call", str(record["tool_call_id"])))
    if record.get("group"):
        rows.append(("group", str(record["group"])))
    rows += [
        ("session", record.get("session") or "none (not from a browser tab)"),
        ("origin", record.get("origin") or "?"),
    ]
    if record.get("error"):
        rows.append(("error", str(record["error"])))
    return rows


def _badges(record: dict[str, Any]) -> list[str]:
    return [
        str(record.get("source", "")),
        *([f"retry {record['retry']}"] if record.get("retry") else []),
        *(["redirected"] if record.get("redirects") else []),
        *(["error"] if record.get("error") else []),
    ]


def _timing(record: dict[str, Any]) -> list[str]:
    """Summary parts: status, time, and the wait before sending when there was one."""
    parts = [str(record.get("status", "no answer")), f"{record.get('ms', '?')} ms"]
    if record.get("wait_ms"):
        parts.append(f"waited {record['wait_ms']} ms")
    return parts


def _http_details(record: dict[str, Any]) -> list[tuple[str, str]]:
    """The request as sent and what came back (ds.util.http's fields), for http and graphql."""
    rows = [("request", f"{record.get('method', '?')} {record.get('url', '')}")]
    if record.get("final_url"):
        rows.append(("ended at", f"{record['final_url']} (after {record.get('redirects')} redirects)"))
    if record.get("request_headers"):
        rows.append(("request headers", _json(record["request_headers"])))
    if record.get("request_body") is not None:
        rows.append(("request body", _json(record["request_body"])))
    answer = [
        f"HTTP {record['status']}" if "status" in record else "no answer",
        record.get("content_type") or "",
        _size(record.get("bytes")) if "bytes" in record else "",
    ]
    rows.append(("response", " · ".join(part for part in answer if part)))
    found = {
        name: record[name] for name in ("cf_ray", "cf_mitigated", "vercel_mitigated", "retry_after") if name in record
    }
    if found:
        rows.append(("response headers", _json(found)))
    if record.get("error_body"):
        rows.append(("response body (start)", str(record["error_body"])))
    timing = [f"{record.get('ms', '?')} ms in all"]
    if record.get("wait_ms"):
        timing.append(f"{record['wait_ms']} ms waiting for the rate budget before sending")
    if record.get("in_flight"):
        timing.append(f"{record['in_flight']} request(s) to {record.get('source')} in flight")
    rows.append(("timing", ", ".join(timing)))
    return rows


def _graphql(record: dict[str, Any]) -> LogView:
    variables = record.get("variables") or {}
    op = record.get("op", "query")
    if "page" in variables:
        op += f" page {variables['page']}"
    parts = [op, *_timing(record)]
    if record.get("rows") is not None:
        parts.append(f"{record['rows']} rows")
    if record.get("objects") is not None:
        parts.append(f"{record['objects']} objects")
    details = [("variables", _json(variables))]
    if record.get("page_info"):
        details.append(("page info", _json(record["page_info"])))
    for name, label in (("errors", "errors"), ("api_message", "message")):
        if record.get(name):
            details.append((f"{record.get('source')} {label}", _json(record[name])))
    if record.get("query"):
        details.append(("query", str(record["query"]).strip()))
    return LogView(" · ".join(parts), _badges(record), details + _http_details(record) + _common(record))


def _http(record: dict[str, Any]) -> LogView:
    parts = [str(record.get("name") or "request"), *_timing(record)]
    if record.get("rows") is not None:
        parts.append(f"{record['rows']} rows")
    return LogView(" · ".join(parts), _badges(record), _http_details(record) + _common(record))


def _agent(record: dict[str, Any]) -> LogView:
    steps = record.get("steps", 0)
    parts = [
        str(record.get("name") or "turn"),
        f"{record.get('ms', '?')} ms",
        f"{steps} tool call{'s' if steps != 1 else ''}",
    ]
    if record.get("input_tokens") is not None:
        parts.append(f"{record['input_tokens']} in / {record.get('output_tokens')} out tokens")
    return LogView(" · ".join(parts), _badges(record), [("prompt", str(record.get("prompt", "")))] + _common(record))


def _tool(record: dict[str, Any]) -> LogView:
    parts = [str(record.get("name", "tool")), f"{record.get('ms', '?')} ms", str(record.get("args", ""))]
    details = [("args", str(record.get("args", "")))]
    # what the tool gave back to the AI (ds.ai.call_log): seen nowhere else, unlike an AI answer
    # (the chat shows it) or an inline edit (the editor does)
    if record.get("response"):
        details.append(("tool response", str(record["response"])))
    return LogView(" · ".join(parts), _badges(record), details + _common(record))


def _default(record: dict[str, Any]) -> LogView:
    skip = {"id", "time", "level", "message", "kind", "source", "session", "origin", "error"}
    fields = {k: v for k, v in record.items() if k not in skip}
    return LogView(record.get("message", ""), _badges(record), [("fields", _json(fields))] + _common(record))


LOG_FORMATS: dict[str, Callable[[dict[str, Any]], LogView]] = {
    "graphql": _graphql,
    "http": _http,
    "agent": _agent,
    "tool": _tool,
}


def _target(record: dict[str, Any]) -> tuple[str, str]:
    """(where the record came from, link text) for State.reveal; ("", "") when unknown.

    The most precise first: the tool call (its chat row), else the chat turn, else the tab or
    cell whose form / page / code ran it (the `slot` it was logged with).
    """
    if record.get("tool_call_id"):
        return f"call-{record['tool_call_id']}", "↖ tool call"
    if record.get("turn"):
        return str(record["turn"]), "↖ chat"
    kind, _, key = str(record.get("slot", "")).partition(":")
    if kind == "tab":
        return f"tab:{key}", f"↖ {key}"
    if kind == "chat":  # a result unfolded in the chat: its row there
        return f"ref-{key}", f"↖ {key} in chat"
    if kind == "cell":
        return f"cell:{key}", "↖ cell"
    return "", ""


def in_focus(record: dict[str, Any], focus: str, tool_call_id: str = "") -> bool:
    """Whether a record belongs to a focus, the reverse of `_target` (same target ids)

    focus: 'call-<id>' (made during that tool call), 'turn-<n>' (that agent turn, its tool
    calls included), 'tab:<name>' (the agent call that made the result, `tool_call_id`, and
    every form run on it, in its tab or unfolded in the chat), 'cell:<id>' (that cell's runs);
    "" for everything.
    """
    kind, _, key = focus.partition(":")
    if focus.startswith("call-"):
        return record.get("tool_call_id") == focus.removeprefix("call-")
    if focus.startswith("turn-"):
        return record.get("turn") == focus
    if kind == "tab":
        made_it = bool(tool_call_id) and record.get("tool_call_id") == tool_call_id
        return made_it or record.get("slot") in {f"tab:{key}", f"chat:{key}"}
    if kind == "cell":
        return record.get("slot") == focus
    return True


def _row(record: dict[str, Any]) -> dict[str, Any]:
    view = LOG_FORMATS.get(record.get("kind", ""), _default)(record)
    target, target_label = _target(record)
    when = dt.datetime.fromtimestamp(record["time"]).strftime("%H:%M:%S")
    plain = {k: v for k, v in record.items() if k != "message"}
    curl = ""
    if record.get("kind") == "graphql":
        # the body of a GraphQL record is its own fields (ds.util.graphql)
        body = {"query": record.get("query", ""), "variables": record.get("variables") or {}}
        curl = curl_command(record | {"request_body": body})
    elif record.get("kind") == "http":
        curl = curl_command(record)
    return {
        "id": str(record["id"]),
        "time": when,
        "kind": record.get("kind", ""),
        "error": bool(record.get("error")),
        "summary": view.summary,
        "badges": [b for b in view.badges if b],
        "details": [
            {"label": label, "text": text, "fold": "1" if label in FOLDED_DETAILS else ""}
            for label, text in view.details
        ],
        "copy": _json(plain),
        "curl": curl,
        "session": str(record.get("session") or ""),
        "target": target,
        "target_label": target_label,
    }


def kinds() -> list[str]:
    """Every kind in the log, for the filter chips (the known ones first)."""
    with _lock:
        seen = {r.get("kind", "") for r in _records}
    return [k for k in LOG_FORMATS if k in seen] + sorted(seen - set(LOG_FORMATS))


def rows(
    kinds_shown: list[str], session: str = "", focus: str = "", tool_call_id: str = ""
) -> tuple[list[dict[str, Any]], int]:
    """(newest MAX_ROWS matching rows, how many match): only `kinds_shown` (all when empty),
    only one session's when `session` is set, only those `in_focus` when `focus` is set."""
    with _lock:
        records = list(_records)
    matching = [
        r
        for r in reversed(records)
        if (not kinds_shown or r.get("kind") in kinds_shown)
        and (not session or r.get("session") == session)
        and in_focus(r, focus, tool_call_id)
    ]
    return [_row(r) for r in matching[:MAX_ROWS]], len(matching)


# -- stats ----------------------------------------------------------------------------


def _rss_bytes() -> tuple[int, str]:
    """(bytes, label) of the backend's memory: current RSS on Linux, else the peak."""
    status = Path("/proc/self/status")
    if status.exists():
        for line in status.read_text().splitlines():
            if line.startswith("VmRSS:"):
                return int(line.split()[1]) * 1024, "memory"
    peak = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    return (peak if sys.platform == "darwin" else peak * 1024), "peak memory"


def _rough_size(value: Any) -> int:
    """About how much memory a session variable holds (cheap; for spotting growth, not exact)."""
    if isinstance(value, pl.DataFrame):
        return int(value.estimated_size())
    if isinstance(value, BaseModel):
        return len(value.model_dump_json())
    return sys.getsizeof(value)


def _mb(n: float) -> str:
    """Bytes as MB, or KB below 1 MB."""
    return f"{n / 1024 / 1024:.1f} MB" if n >= 1024 * 1024 else f"{n / 1024:.0f} KB"


def stats(namespace: dict[str, Any], skip: tuple[str, ...]) -> str:
    """One line: start.gg requests in the last 60 s against the limit, the backend's memory, and
    this session's variables (count, rough size). skip: names that aren't the user's (pl, db)."""
    now = time.time()
    with _lock:
        recent = sum(
            1
            for r in _records
            if r.get("kind") == "graphql" and r.get("source") == "startgg" and now - r["time"] <= _WINDOW
        )
    rss, label = _rss_bytes()
    names = [n for n in namespace if not n.startswith("_") and n not in skip and not isinstance(namespace[n], type)]
    size = sum(_rough_size(namespace[n]) for n in names)
    return " · ".join(
        [
            f"start.gg: {recent} / {MAX_REQUESTS_PER_MINUTE} requests in the last 60 s",
            f"backend {label}: {_mb(rss)}",
            f"variables: {len(names)}, about {_mb(size)}",
            f"log: {len(_records)} / {MAX_RECORDS} records",
        ]
    )
